// Runs in the existing real-main/preload fixture with isolated data only.
const assert=require('node:assert/strict');
module.exports=async({run,click,disk,shot,window})=>{
  window.setSize(1280,900);
  const active=()=>disk().data.timetables.tables.find(t=>t.id===disk().data.timetables.activeId);
  const pickFile=async(text,name)=>run(`(()=>{const dt=new DataTransfer();dt.items.add(new File([${JSON.stringify(text)}],${JSON.stringify(name)},{type:'text/plain'}));const i=document.querySelector('#desktop-csv-file');i.files=dt.files;i.dispatchEvent(new Event('change',{bubbles:true}));return true})()`);
  const wait=async check=>{for(let i=0;i<80;i++){if(await run(check))return;await new Promise(r=>setTimeout(r,40));}throw Error('Parity UI did not render: '+check);};
  await click('[data-view="courses"]');await click('#desktop-open-course-settings');await click('#desktop-open-import');
  const before=active().courses.length;
  const csv='课程名,教师,教室,星期,开始节,结束节,周次\n迁移验证课程,虚构老师,101,1,1,2,"1,3"\n错误课程,乙,102,2,0,2,1-3';
  await pickFile(csv,'parity.csv');await wait('document.querySelector("#desktop-course-tools-dialog").open');
  assert.equal(await run('document.querySelector("#desktop-course-tools-dialog").getBoundingClientRect().width'),820,'import preview shares the standard sheet width');
  assert.equal(active().courses.length,before,'preview never writes');
  assert.equal(await run('document.querySelector("#desktop-confirm-course-file").disabled'),true);
  await shot('parity-import-preview-wide.png');
  await run(`(()=>{const i=document.querySelector('[data-line="1"][data-file-field="periodStart"]');i.focus();i.value='1';i.dispatchEvent(new Event('change',{bubbles:true}));return true})()`);
  assert.equal(await run('document.activeElement.dataset.fileField'),'periodStart','preview validation preserves editing focus');
  assert.equal(await run('document.querySelector("#desktop-confirm-course-file").disabled'),false,'repairing a CSV row revalidates the preview');
  await run(`(()=>{const i=document.querySelector('[data-line="1"][data-file-field="periodStart"]');i.value='0';i.dispatchEvent(new Event('change',{bubbles:true}));return true})()`);
  await click('[data-file-select="1"]');await click('#desktop-confirm-course-file');
  assert.equal(active().courses.length,before+1);const course=active().courses.find(c=>c.title==='迁移验证课程');assert.ok(course);
  await click('#desktop-open-course-settings');await click('#desktop-open-batch');
  await run(`(()=>{const row=[...document.querySelectorAll('.desktop-batch-course')].find(r=>r.dataset.courseId===${JSON.stringify(course.id)});row.querySelector('[data-field=title]').value='迁移验证课程改名';row.querySelector('[data-field=teacher]').value='新老师';row.querySelector('[data-field=location]').value='202';row.querySelector('[data-field=periodEnd]').value='1';return true})()`);
  await click('#desktop-save-batch');
  assert.equal(active().courses.find(c=>c.id===course.id).title,'迁移验证课程改名');assert.equal(active().courses.find(c=>c.id===course.id).createdAt,course.createdAt);
  await run('document.querySelector("#desktop-course-week").value="1";document.querySelector("#desktop-course-week").dispatchEvent(new Event("change"));true');
  await click(`[data-course-id="${course.id}"]`);await click('#desktop-adjust-course');
  assert.equal(await run('document.querySelector("#desktop-adjust-form").hidden'),false);
  assert.equal(await run('document.querySelector("#desktop-course-tools-dialog").getBoundingClientRect().width'),820,'single lesson adjustments share the standard sheet width');
  await shot('parity-adjust-wide.png');
  const target=await run(`(async()=>{const c=await import('../shared/packages/core/src/semester-calendar.mjs');return c.today()})()`);
  await run(`(()=>{const f=document.querySelector('#desktop-adjust-form');f.elements.date.value=${JSON.stringify(target)};f.elements.periodStart.value='3';f.elements.periodEnd.value='4';f.elements.location.value='303';f.elements.reason.value='虚构调课验收';f.requestSubmit();return true})()`);
  assert.equal(active().adjustments.find(a=>a.courseId===course.id).action,'move');
  assert.equal(await run(`document.querySelector('[data-course-id="${course.id}"][data-occurrence-status=moved]')!==null`),true);
  assert.equal(await run(`document.querySelectorAll('[data-course-id="${course.id}"][data-occurrence-status=normal]').length`),1);
  await shot('parity-move-week-wide.png');
  await click('[data-view="today"]');
  assert.equal(await run('document.querySelector("#desktop-today-list").textContent.includes("本次调入")'),true);
  assert.equal(await run('document.querySelector("#desktop-today-course-state")!==null'),true);
  await click('[data-view="calendar"]');
  await run(`document.querySelector('#desktop-calendar-jump').value=${JSON.stringify(target)};document.querySelector('#desktop-calendar-jump').dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('[data-cal-view=week]').click();true`);
  assert.equal(await run(`document.querySelector('#desktop-calendar-grid').textContent.includes('迁移验证课程改名')`),true);
  await run(`(()=>{const b=[...document.querySelectorAll('#desktop-calendar-grid [data-cal-entry]')].find(b=>b.textContent.includes('迁移验证课程改名')&&b.textContent.includes('调入'));b.click();return true})()`);
  await click('[data-cal-course-adjust]');
  await run(`document.querySelector('#desktop-adjust-form [name=action]').value='cancel';document.querySelector('#desktop-adjust-form [name=action]').dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#desktop-adjust-form').requestSubmit();true`);
  assert.equal(active().adjustments.find(a=>a.courseId===course.id).action,'cancel');
  await click(`[data-course-id="${course.id}"][data-occurrence-status=cancelled]`);await click('#desktop-adjust-course');await click('#desktop-restore-adjustment');
  assert.equal(active().adjustments.some(a=>a.courseId===course.id),false);
  // A stale preview cannot overwrite newly changed table data.
  await click('#desktop-open-course-settings');await click('#desktop-open-import');await pickFile(csv,'cancel.csv');await wait('document.querySelector("#desktop-file-preview").hidden===false');
  const previousName=active().name;
  await run(`document.querySelector('#desktop-semester-form [name=name]').value='模拟异步修改';document.querySelector('#desktop-semester-form').requestSubmit();true`);
  await click('[data-file-select="1"]');
  await click('#desktop-confirm-course-file');
  assert.equal(await run('document.querySelector("#desktop-file-preview [role=alert]").textContent.includes("已变化")'),true);
  await run('document.querySelector("#desktop-file-preview [data-close-tool]").click();true');assert.equal(active().courses.length,before+1);
  await run(`document.querySelector('#desktop-semester-form [name=name]').value=${JSON.stringify(previousName)};document.querySelector('#desktop-semester-form').requestSubmit();true`);
  // Explicit ICS export uses the active course projection; roundtrip adds nothing.
  const ics=await run(`(async()=>{const m=await import('./course-files.mjs');const t=JSON.parse(localStorage.getItem('jiwei-desktop-timetables-v1'));return m.exportCourseIcs(t.tables.find(table=>table.id===t.activeId))})()`);
  await click('#desktop-open-course-settings');await click('#desktop-open-import');await pickFile(ics,'roundtrip.ics');await wait('!document.querySelector("#desktop-file-preview").hidden');
  assert.equal(await run('document.querySelector("#desktop-file-summary").textContent.includes("待修正 0 行")'),true);
  await click('#desktop-confirm-course-file');assert.equal(active().courses.length,before+1);
  // Save a cancellation for restart/moved-directory verification.
  await click(`[data-course-id="${course.id}"]`);await click('#desktop-adjust-course');
  await run("document.querySelector('#desktop-adjust-form [name=action]').value='cancel';document.querySelector('#desktop-adjust-form [name=action]').dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#desktop-adjust-form').requestSubmit();true");
  await click('[data-view="settings"]');await click('[data-reading-field="size"][data-reading-value="large"]');await click('[data-reading-field="density"][data-reading-value="comfortable"]');
  assert.equal(disk().data.preferences.reading.size,'large');assert.equal(disk().data.preferences.reading.density,'comfortable');
  await click('[data-view="courses"]');
  assert.equal(await run('getComputedStyle(document.documentElement).getPropertyValue("--desktop-period-height").trim()'),'82px');
  assert.equal(await run('getComputedStyle(document.querySelector(".desktop-timetable-course strong")).fontSize'),'16px');
  window.setSize(900,700);await click(`[data-course-id="${course.id}"]`);await click('#desktop-adjust-course');await shot('parity-adjust-compact-large.png');
  assert.equal(await run('(()=>{const d=document.querySelector("#desktop-course-tools-dialog").getBoundingClientRect();return d.right<=innerWidth&&d.bottom<=innerHeight})()'),true);
  await click('#desktop-adjust-form [data-close-tool]');
  console.log('PASS: parity CSV repair/skip/cancel, batch identity, one-lesson move/cancel/restore, today and calendar consistency, ICS roundtrip, large reading/density and compact overlays.');
};
